import math
from sympy import factorials, sum

def derangement(n):
    """Calculates the number of derangements D_n."""
    d_n = 0
    for k in range(n + 1):
        term = ((-1)**k) / factorials(k)
        d_n += term
    return round(math.factorial(n) * d_n)

print(f"D_16: {derangement(16)}")

import math
from fractions import Fraction

def derangement(n):
    """Calculates the number of derangements D_n."""
    sum_val = 0
    for k in range(n + 1):
        term = Fraction((-1)**k, math.factorial(k))
        sum_val += term

    return round(math.factorial(n) * sum_val)

print(f"D_16: {derangement(16)}")

